pub(super) fn dispatch(
    engine: &MindLeak,
    name: &str,
    args: &Value,
) -> Option<Result<Value, String>> {
    match name {
        "graph_snapshot" => Some((|| {
            let seed = opt_str(args, "seed");
            let limit = opt_i64(args, "limit", 50).clamp(1, 500) as usize;
            let sub = engine
                .snapshot(seed.as_deref(), limit)
                .map_err(|e| e.to_string())?;
            Ok(text_result(&json!(sub)))
        })()),
        "prune_graph" => Some((|| {
            let outcome = engine.prune().map_err(|e| e.to_string())?;
            Ok(text_result(&json!(outcome)))
        })()),
        "graph_stats" => Some((|| {
            let (nodes, edges) = engine.counts().map_err(|e| e.to_string())?;
            let (unembedded, split_identity) = engine.health().map_err(|e| e.to_string())?;
            let data = json!({
                "nodes": nodes,
                "active_edges": edges,
                "unembedded_nodes": unembedded,
                "split_identity_nodes": split_identity,
            });
            let mut markdown = format!(
                "| MindLeak graph | |\n|---|--:|\n| Nodes | {nodes} |\n| Active edges | {edges} |"
            );
            // Only shown when true. A health row that is always present is one
            // readers learn to skip, which is how both of these stayed invisible.
            if unembedded > 0 {
                markdown.push_str(&format!(
                    "\n| Not recallable (no embedding) | {unembedded} |"
                ));
            }
            if split_identity > 0 {
                markdown.push_str(&format!(
                    "\n| Split identity (absolute path) | {split_identity} |"
                ));
            }
            Ok(rendered_result(markdown, &data))
        })()),
        "export_graph" => Some((|| {
            let export = engine.export_graph().map_err(|e| e.to_string())?;
            Ok(text_result(&json!(export)))
        })()),
        "backup_database" => Some((|| {
            let path = req_str(args, "path")?;
            engine.backup_database(&path).map_err(|e| e.to_string())?;
            Ok(text_result(&json!({ "backed_up": true, "path": path })))
        })()),
        "reset_database" => Some((|| {
            let confirmation = req_str(args, "confirm")?;
            let outcome = engine
                .reset_database(&confirmation)
                .map_err(|e| e.to_string())?;
            Ok(text_result(&json!(outcome)))
        })()),
        "list_agents" => Some((|| {
            let agents = engine.list_agents().map_err(|e| e.to_string())?;
            Ok(text_result(&json!({ "agents": agents })))
        })()),
        "working_set" => Some((|| {
            let agent = req_str(args, "agent")?;
            let limit = args
                .get("limit")
                .and_then(Value::as_i64)
                .map(|value| value.clamp(1, 32) as usize);
            let items = engine
                .working_set(&agent, limit)
                .map_err(|e| e.to_string())?;
            Ok(text_result(&json!({ "items": items })))
        })()),
        "evidence_for" => Some((|| {
            let agent = req_str(args, "agent_id")?;
            let started_at = required_i64(args, "started_at")?;
            let ended_at = required_i64(args, "ended_at")?;
            let evidence = engine
                .evidence_for(
                    opt_str(args, "task_id").as_deref(),
                    &agent,
                    started_at,
                    ended_at,
                )
                .map_err(|e| e.to_string())?;
            // An empty bundle is not evidence, and handing one back invites
            // submitting it. Conformance then reports "no provenance-bearing
            // mutation" and parks the task at needs_human, awaiting a human who
            // cannot do anything about it -- the cause is always that nothing
            // was ingested into this window, and the remedy is knowable here.
            // Refusing at the point of construction is the same rule the
            // argument guard applies: a call that cannot produce a useful
            // result says so, rather than succeeding emptily.
            if evidence.changed_node_ids.is_empty()
                && evidence.commit_ids.is_empty()
                && evidence.execution_ids.is_empty()
            {
                return Err(format!(
                    "no evidence in {started_at}..{ended_at} for {agent}: nothing was ingested \
                     into this window, so there is nothing to complete a task with. Ingest the \
                     work first -- `ingest_commit` with `changed_files` for a commit, \
                     `ingest_execution` for a command -- then ask again. Submitting an empty \
                     bundle records a needs_human verdict no human can resolve."
                ));
            }
            Ok(text_result(&json!(evidence)))
        })()),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::super::tests::{call_ok, content_text};
    use super::super::{call, list};
    use mindleak_core::MindLeak;
    use serde_json::{json, Value};

    /// Measured on the live board: forty audits carried "evidence contains no
    /// provenance-bearing mutation", sixteen of them raised *after* the
    /// argument guard shipped, by two different agents. Every one of those
    /// bundles was completely empty -- commits=0 changed=0 execs=0
    /// provenance=0 -- so the misspelt-argument defect was a cause and not the
    /// cause. The dominant one is an agent asking for evidence over a window
    /// nothing was ingested into, getting a well-formed envelope containing
    /// nothing, and submitting it. Conformance then parks the task at
    /// needs_human, which reads as "a human must judge this" when in fact
    /// nobody can: the work was never recorded.
    #[test]
    fn an_empty_window_is_refused_rather_than_returned_as_evidence() {
        let engine = MindLeak::open_in_memory().unwrap();
        let error = call(
            &engine,
            &json!({
                "name": "evidence_for",
                "arguments": { "agent_id": "agent-a", "started_at": 1, "ended_at": 2 }
            }),
        )
        .unwrap_err();

        assert!(error.contains("no evidence"), "says there is none: {error}");
        assert!(
            error.contains("ingest_commit"),
            "names the remedy rather than only the symptom: {error}"
        );
        assert!(
            error.contains("needs_human"),
            "explains why submitting it anyway is worse than stopping: {error}"
        );
    }

    /// The refusal must be narrow. A window that caught real work still returns
    /// it, or the guard would block the path it exists to protect.
    #[test]
    fn a_window_containing_work_still_returns_evidence() {
        let engine = MindLeak::open_in_memory().unwrap();
        call_ok(
            &engine,
            "ingest_execution",
            json!({
                "command": "cargo test",
                "exit_code": 0,
                "changed_files": ["src/lib.rs"],
                "timestamp": 100,
                "agent": "agent-a"
            }),
        );

        let result = call_ok(
            &engine,
            "evidence_for",
            json!({ "agent_id": "agent-a", "started_at": 90, "ended_at": 110 }),
        );
        let value: Value = serde_json::from_str(&content_text(&result)).unwrap();
        assert!(
            !value["changed_node_ids"].as_array().unwrap().is_empty(),
            "real work in the window is still returned: {value}"
        );
    }

    #[test]
    fn graph_stats_returns_counts() {
        let engine = MindLeak::open_in_memory().unwrap();
        call_ok(
            &engine,
            "ingest_file",
            json!({ "path": "a.rs", "content": "fn a() {}" }),
        );
        let result = call_ok(&engine, "graph_stats", json!({}));
        // The chat-facing content renders as a Markdown table...
        let text = content_text(&result);
        assert!(text.contains("Nodes"));
        assert!(text.contains("Active edges"));
        // ...while the structured JSON is preserved for programmatic consumers.
        assert!(result["structuredContent"]["nodes"].is_number());
        assert!(result["structuredContent"]["active_edges"].is_number());
    }

    #[test]
    fn working_set_uses_bound_session_agent_and_hard_cap() {
        let engine = MindLeak::open_in_memory().unwrap().with_working_set_size(1);
        call_ok(
            &engine,
            "ingest_file",
            json!({ "path": "src/a.rs", "content": "fn a() {}", "agent": "agent-a" }),
        );
        call_ok(
            &engine,
            "ingest_file",
            json!({ "path": "src/b.rs", "content": "fn b() {}", "agent": "agent-a" }),
        );

        let result = call_ok(
            &engine,
            "working_set",
            json!({ "limit": 32, "agent": "agent-a" }),
        );
        let payload: Value = serde_json::from_str(&content_text(&result)).unwrap();

        assert_eq!(payload["items"].as_array().unwrap().len(), 1);
        assert!(payload["items"][0]["attention"].is_number());
        assert!(payload["items"][0]["observation_count"].is_number());
        assert!(engine
            .telemetry_snapshot(20)
            .unwrap()
            .by_name
            .iter()
            .any(|metric| metric.name == "working_set" && metric.calls == 1));

        let schema = list()
            .into_iter()
            .find(|tool| tool["name"] == "working_set")
            .unwrap();
        assert_eq!(schema["inputSchema"]["properties"]["limit"]["maximum"], 32);
    }

    #[test]
    fn working_set_errors_without_bound_session_agent() {
        let engine = MindLeak::open_in_memory().unwrap();
        let error = call(&engine, &json!({ "name": "working_set", "arguments": {} })).unwrap_err();
        assert!(error.contains("agent"));
    }

    #[test]
    fn lifecycle_tools_export_backup_and_confirm_reset() {
        let engine = MindLeak::open_in_memory().unwrap();
        call_ok(
            &engine,
            "ingest_file",
            json!({ "path": "src/lib.rs", "content": "pub fn mindleak() {}" }),
        );

        let export: Value =
            serde_json::from_str(&content_text(&call_ok(&engine, "export_graph", json!({}))))
                .unwrap();
        assert!(export["nodes"]
            .as_array()
            .unwrap()
            .iter()
            .any(|node| node["id"] == "artifact:src/lib.rs"));

        let path =
            std::env::temp_dir().join(format!("mindleak-mcp-backup-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        call_ok(
            &engine,
            "backup_database",
            json!({ "path": path.to_str().unwrap() }),
        );
        assert!(path.exists());
        std::fs::remove_file(path).unwrap();

        let rejected = call(
            &engine,
            &json!({ "name": "reset_database", "arguments": { "confirm": "yes" } }),
        )
        .unwrap_err();
        assert!(rejected.contains("RESET MINDLEAK"));
        let reset = call_ok(
            &engine,
            "reset_database",
            json!({ "confirm": "RESET MINDLEAK" }),
        );
        assert!(content_text(&reset).contains("nodes_removed"));
        assert_eq!(engine.counts().unwrap(), (0, 0));
    }

    #[test]
    fn evidence_for_returns_attributed_mutation_provenance() {
        let engine = MindLeak::open_in_memory().unwrap();
        call_ok(
            &engine,
            "ingest_execution",
            json!({
                "command": "cargo check",
                "exit_code": 0,
                "changed_files": ["src/lib.rs"],
                "timestamp": 100,
                "agent": "agent-a"
            }),
        );

        let result = call_ok(
            &engine,
            "evidence_for",
            json!({
                "task_id": "task:proof",
                "agent_id": "agent-a",
                "started_at": 90,
                "ended_at": 110
            }),
        );
        let evidence: Value = serde_json::from_str(&content_text(&result)).unwrap();
        assert_eq!(evidence["schema_version"], 1);
        assert_eq!(evidence["task_id"], "task:proof");
        assert_eq!(evidence["changed_node_ids"][0], "artifact:src/lib.rs");
        assert_eq!(
            evidence["successful_execution_ids"]
                .as_array()
                .unwrap()
                .len(),
            1
        );
        assert!(evidence["provenance"]
            .as_array()
            .unwrap()
            .iter()
            .any(|fact| fact["relation"] == "modified"));
    }
}
